import sys
input = sys.stdin.readline

def read_ints():
    return list(map(int, input().split()))

def main():
    n = int(input())
    heights = read_ints()

    while True:
        changed = False
        for j in range(n - 1):
            if heights[j] + 2 <= heights[j + 1]:
                transfer = (heights[j + 1] - heights[j]) // 2
                heights[j] += transfer
                heights[j + 1] -= transfer
                changed = True
        if not changed:
            break

    print(' '.join(map(str, heights)))

if __name__ == "__main__":
    main()
